"use client";

import type { SVGProps } from "react";
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";

import { cn } from "@/lib/utils";
import { controlChecked } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Ink mail Checkbox: a 1rem box with a 0.375rem corner and a grey edge on the
 * black page. Checked or mixed, it fills with the primary button's flat
 * off-white, and the black tick or dash sits on it. Base UI owns the checked
 * state, so a controlled parent passes `checked` straight through.
 */
function Checkbox({
  className,
  indeterminate,
  ...props
}: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      indeterminate={indeterminate}
      className={cn(
        "peer inline-flex size-4 shrink-0 items-center justify-center rounded-sm border border-(--control) bg-transparent text-primary-foreground",
        "transition-[background-color,border-color] duration-fast ease-out",
        "outline-none focus-visible:ring-3 focus-visible:ring-ring",
        "data-[disabled]:cursor-not-allowed data-[disabled]:border-(--line-strong) data-[disabled]:bg-secondary data-[disabled]:text-(--foreground-disabled)",
        controlChecked,
        "data-[indeterminate]:border-primary data-[indeterminate]:bg-primary",
        "data-[disabled]:data-[indeterminate]:border-(--line-strong) data-[disabled]:data-[indeterminate]:bg-muted data-[disabled]:data-[indeterminate]:text-(--foreground-disabled)",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="flex size-full items-center justify-center text-current"
      >
        {indeterminate ? <MinusIcon aria-hidden="true" className="size-3" /> : <CheckIcon aria-hidden="true" className="size-3" />}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
Checkbox.displayName = "Checkbox";

export { Checkbox };

// "ph:check" and "ph:minus" from Phosphor,
// the icon library this system pairs with, drawn inline so the installed
// component loads no icon at runtime. [BD-1029]
function CheckIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 256 256" aria-hidden="true" {...props}>
      <path fill="currentColor" d="m229.66 77.66l-128 128a8 8 0 0 1-11.32 0l-56-56a8 8 0 0 1 11.32-11.32L96 188.69L218.34 66.34a8 8 0 0 1 11.32 11.32"/>
    </svg>
  );
}
function MinusIcon(props: SVGProps<SVGSVGElement>) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 256 256" aria-hidden="true" {...props}>
      <path fill="currentColor" d="M224 128a8 8 0 0 1-8 8H40a8 8 0 0 1 0-16h176a8 8 0 0 1 8 8"/>
    </svg>
  );
}
